# Wire-level wrappers from mcu_protocol.py (our work).
# Algorithm intent derived from upstream prtouch.py `dirzctl` usage
# (prtouch.py:570-700, GPL-3, wangyulong) — note the upstream v1/v2 prtouch
# uses a SEPARATE MCU object called `dirzctl` to BOTH capture step counts AND
# drive Z motion. In v3, motion is generated by Klipper's standard stepper
# infrastructure (toolhead.manual_move + drip moves) and the `prtouch_step`
# subsystem is capture-only. Hence StepCapture, not StepController.
"""Stepper-position-counter capture for probe motions.

The K2's prtouch_v3 MCU module captures per-tick snapshots of the X/Y/Z
stepper counters during a probing motion. The host correlates these against
pressure samples to interpolate the exact Z position at the moment of contact.

The wire layer exposes:

    config_prtouch_step oid=%c oid_xstp=%u oid_ystp=%u oid_zstp=%u swp_pin=%u
    start_prtouch_step  oid=%c aqc_tick=%u
    stop_prtouch_step   oid=%c
    read_prtouch_step   oid=%c idx=%c len=%c          -> resault_prtouch_step
    cont_prtouch_step   oid=%c

Responses:

    resault_prtouch_step     oid=%c buf_len=%c idx=%c len=%c ticks=%.*s datas=%.*s
        — windowed binary dump of the captured ticks+step deltas (zip-compressed
          on the MCU; decompressed host-side from the int16 stream).
    resault_prtouch_step_cnt oid=%c cnt_x=%i cnt_y=%i cnt_z=%i
        — one-shot snapshot of the three counters (instantaneous).

StepCapture mirrors the calling shape of the upstream `dirzctl` object so
the eventual `probe_by_step` port stays a near-line-by-line transcription
from prtouch.py:619-658.

Capture format (per `pr_step` struct at src/prtouch_v3.c:636, 540 bytes,
embedded `step_buf` at offset +24, 512 bytes total):

  The MCU keeps a flat 64-entry capture buffer pair:
    buf_step.buf_tick[64]  : uint32_t absolute MCU ticks
    buf_step.buf_zpos[64]  : int32_t  Z-stepper position (in steps)

  **Step capture is NOT zip-compressed** — unlike `pr_pres` and `pr_apax`
  which carry 4-channel `syst_zip` ring buffers, `pr_step` writes raw
  absolute values. Host-side decompression is therefore unnecessary; the
  `read_prtouch_step` response payload is a packed pair of uint32_t and
  int32_t arrays.

  (See docs/MCU_SYMBOLS.md "step_buf" — DWARF struct dump 2026-05-23
  resolved an earlier wrong assumption that step shared the pres `_zip`
  scheme. It does not.)

The trigger loop in probe_by_step only needs the first and last
(tick, step) pairs to linearly interpolate the contact Z, so reading the
last 2 entries via `read_prtouch_step len=2` is the normal hot path.
"""

import logging

from . import mcu_protocol as proto


class StepCapture:
    """Captures stepper-position samples during a probing motion.

    Owns the prtouch_v3 step OID and the MCU-side commands. Used by
    motion.py / endstop.py to interpolate the contact Z position after
    a successful trigger.

    Usage (matching the upstream `dirzctl` calling shape):

        step = StepCapture(mcu, cfg)
        step.configure(oid, oid_xstp, oid_ystp, oid_zstp, swp_pin)
        step.attach_steppers([z_stepper])
        step.start_capture(acq_tick=int(mcu.seconds_to_clock(0.00078125)))
        ... motion runs ...
        snapshots, current_tick = step.get_params()
        step.stop_capture()
    """

    def __init__(self, mcu_obj, cfg):
        self.mcu = mcu_obj
        self.cfg = cfg
        # Defer wrappers until mcu_identify has loaded the MCU dictionary.
        self.proto = None

        self.oid = None
        self.swp_pin = None
        # OIDs of the bound stepper objects (X, Y, Z). filled by configure().
        self.bound_oids = (None, None, None)
        # Optional Klipper stepper objects — populated via attach_steppers().
        # Provides get_step_dist() and microstep_base for mm/step math.
        self.steppers = []
        # Match upstream prtouch.py's dirzctl.step_base — multiplier from the
        # config that lets prtouch reason in "base-steps" (microsteps × N).
        self.step_base = getattr(cfg, "step_base", 16)
        # MCU clock frequency — used to convert ticks → seconds. Cached lazily.
        self._mcu_freq = None

        # Captured samples — list of dicts shaped to match upstream's
        # `dirzctl.get_params()` output:
        #     [{'tick': <mcu_ticks>, 'step': <z_step_count>}, ...]
        # The first entry is the capture-start anchor; subsequent entries are
        # per-tick snapshots until the motion completes (or stop_capture).
        # Upstream's trigger loop only consults entries 0 and 1 (start + end).
        self._snapshots = []
        self._capture_start_tick = None
        self._capture_active = False
        # When the response stream reports motion-complete, this flips true —
        # upstream's `len(all_params) == 2` check is replaced by this flag.
        self._motion_complete = False

        # Register a response handler for the streaming step dump. Until we
        # have live captures to verify the binary format, the handler stashes
        # the raw payload; decoders below will parse it. See TODO(decode).
        self._raw_response_log = []

    # ---- lifecycle ----------------------------------------------------

    def configure(self, oid, oid_xstp, oid_ystp, oid_zstp, swp_pin):
        """Bind to the X/Y/Z stepper OIDs and the trigger / sample-wait pin."""
        self.oid = oid
        self.swp_pin = swp_pin
        self.bound_oids = (oid_xstp, oid_ystp, oid_zstp)

    def build_config(self):
        """Queue step-capture configuration after mcu_identify.

        `_handle_mcu_identify()` patches `bound_oids` with the actual X/Y/Z
        stepper OIDs before Klipper executes registered config callbacks.
        """
        self.proto = proto.StepCommands(self.mcu, self.oid)
        oid_xstp, oid_ystp, oid_zstp = self.bound_oids
        if None in (self.oid, oid_xstp, oid_ystp, oid_zstp, self.swp_pin):
            raise self.mcu.get_printer().config_error(
                "K2-PRTouch step capture was not fully bound before config"
            )
        self.mcu.add_config_cmd(
            "config_prtouch_step oid=%d oid_xstp=%d oid_ystp=%d "
            "oid_zstp=%d swp_pin=%s"
            % (
                self.oid,
                oid_xstp,
                oid_ystp,
                oid_zstp,
                self.swp_pin,
            )
        )

    def attach_steppers(self, steppers):
        """Provide Klipper stepper objects for mm/step conversion.

        The first stepper in the list is treated as the canonical Z axis
        (matches upstream's `dirzctl.steppers[0]`).
        """
        self.steppers = list(steppers)

    def start_capture(self, acq_tick=None):
        """Begin per-tick step capture.

        acq_tick — sample period in MCU ticks. Default 0.78125 ms worth
        (matches the pressure sampler rate so the two streams can be
        aligned tick-for-tick).
        """
        if self.oid is None:
            raise RuntimeError("StepCapture: configure() must be called before start_capture()")
        if acq_tick is None:
            acq_tick = int(self.mcu.seconds_to_clock(0.00078125))

        # Reset captured state for the new run
        self._snapshots = []
        self._motion_complete = False
        self._raw_response_log = []
        # Anchor the capture start tick — used as the prefix-sum offset
        # when reconstructing absolute ticks from zip deltas.
        self._capture_start_tick = self.mcu.get_query_slot(self.oid) if hasattr(
            self.mcu, "get_query_slot"
        ) else None

        self.proto.start_capture(self.oid, acq_tick)
        self._capture_active = True

    def stop_capture(self):
        if not self._capture_active:
            return
        try:
            self.proto.stop_capture(self.oid)
        finally:
            self._capture_active = False

    def continue_capture(self):
        """Resume capture after a pause / buffer-flush."""
        if self.oid is None:
            raise RuntimeError("StepCapture: configure() must be called before continue_capture()")
        self.proto.continue_capture(self.oid)

    def send_heart_beat(self):
        """Keep the capture session alive — paired with the trigger loop's
        delay_s. Upstream's `dirzctl.send_heart_beat()` semantically maps
        to `continue_capture()` on the v3 wire layer."""
        if self._capture_active:
            self.continue_capture()

    # ---- snapshot / one-shot reads ------------------------------------

    def get_step_cnt(self):
        """One-shot snapshot of (cnt_x, cnt_y, cnt_z).

        Reads the most recent `resault_prtouch_step_cnt` from the response
        log. The MCU emits one of these in response to certain wire commands
        (likely whenever `read_prtouch_step` is called) — exact emission
        rules need live verification (TODO).
        """
        # The dedicated `read_prtouch_step` returns RESP_STEP, not
        # RESP_STEP_CNT. On the MCU side, RESP_STEP_CNT appears to be
        # emitted as a side-effect of certain commands. Until we observe it
        # live, fall back to reading the last recorded snapshot.
        return self._latest_step_cnt

    def read_buffer(self, idx=0, length=None):
        """Read a window of captured (tick, zpos) pairs.

        Returns a list of dicts: [{'tick': int, 'step': int}, ...].

        Per DWARF (docs/MCU_SYMBOLS.md `step_buf`), the response is a
        flat pair of arrays — uint32_t[len] of ticks and int32_t[len] of
        Z-stepper positions, packed little-endian in the `ticks=` and
        `datas=` blobs. No decompression needed (step is the only one of
        the three subsystems that doesn't zip-encode).
        """
        if length is None:
            length = self.cfg.pi_count
        raw = self.proto.read_buffer(self.oid, idx=idx, length=length)
        return self._decode_step_response(raw)

    # ---- upstream-API compatibility shims -----------------------------

    def get_params(self):
        """Mirror upstream `dirzctl.get_params()` — returns (snapshots, tick).

        Upstream signature:
            (all_params, tick) = self.obj.dirzctl.get_params()
            if len(all_params) == 2:
                # motion complete — caller returns triggered=True
                ...

        We return the buffered snapshot list and the most-recent MCU tick.
        Callers can apply the same `len(all_params) == 2` motion-complete
        heuristic; see `_motion_complete` for the explicit flag.
        """
        current_tick = self.mcu.estimated_print_time(
            self.mcu.get_printer().get_reactor().monotonic()
        ) if hasattr(self.mcu, "estimated_print_time") else 0
        return list(self._snapshots), current_tick

    def check_and_run(self, *args, **kwargs):
        """Compatibility shim — upstream dirzctl exposes `check_and_run` to
        DRIVE motion. In v3 we don't drive motion through prtouch_v3; the
        Z axis is moved via Klipper's standard `toolhead.manual_move` /
        drip-move infrastructure. Calling this is therefore a no-op here
        and indicates the caller is using the wrong path — log a warning
        so the port surface gets caught early.
        """
        logging.warning(
            "StepCapture.check_and_run called — v3 step is capture-only; "
            "motion must be driven via toolhead.manual_move or a drip-move. "
            "args=%r kwargs=%r", args, kwargs
        )

    # ---- mm/step helpers ----------------------------------------------

    def get_step_dist(self):
        """mm-per-step of the Z axis (first attached stepper)."""
        if not self.steppers:
            return 0.0
        return self.steppers[0].get_step_dist()

    @property
    def mcu_freq(self):
        """MCU clock frequency in Hz — used for tick → seconds conversion."""
        if self._mcu_freq is None:
            # Klipper exposes this via mcu.get_constants() or via inverse
            # of seconds_to_clock(1.0). The latter is universally available.
            self._mcu_freq = self.mcu.seconds_to_clock(1.0)
        return self._mcu_freq

    # ---- private: response handlers -----------------------------------

    _latest_step_cnt = (0, 0, 0)

    def _handle_step_response(self, params):
        """RESP_STEP (resault_prtouch_step) — streaming dump.

        Stashed raw; decoded lazily by read_buffer / _decode_zip_response.
        Also drives the motion-complete heuristic: a response with
        `len == 0` indicates the MCU has flushed its final buffer and
        motion is complete (TODO — verify against live capture).
        """
        self._raw_response_log.append(params)
        if params.get("len", 0) == 0:
            self._motion_complete = True

    def _handle_step_cnt_response(self, params):
        """RESP_STEP_CNT (resault_prtouch_step_cnt) — one-shot snapshot."""
        self._latest_step_cnt = (
            params.get("cnt_x", 0),
            params.get("cnt_y", 0),
            params.get("cnt_z", 0),
        )

    def _decode_step_response(self, raw):
        """Decode a `resault_prtouch_step` payload into [{tick, step}, ...].

        Per `step_buf` (DWARF, docs/MCU_SYMBOLS.md):
            buf_tick : uint32_t[64]  — absolute MCU ticks
            buf_zpos : int32_t[64]   — Z-stepper position in steps

        On-wire blobs are little-endian packed arrays of the same width
        (ARM Cortex-M is LE; Klipper's sendf uses native order for `%.*s`
        with binary payloads). Length matches the `len=` field in the
        response header.

        TODO(verify-live): endianness and signedness assumed but not yet
        confirmed against a live K2 capture. The trigger loop in
        probe_by_step only consults entries 0 and -1, so even an off-by-one
        or signed/unsigned confusion would still produce useful relative
        timing. Sanity-check on first live run by comparing decoded ticks
        against `mcu.estimated_print_time(reactor.monotonic())` deltas.
        """
        if not raw:
            return []
        ticks_blob = raw.get("ticks", b"")
        datas_blob = raw.get("datas", b"")
        if not ticks_blob or not datas_blob:
            return []

        import struct
        # Sanity-check: ticks and datas should each be 4 × len bytes.
        n_ticks = len(ticks_blob) // 4
        n_datas = len(datas_blob) // 4
        n = min(n_ticks, n_datas)
        if n == 0:
            return []

        ticks = struct.unpack(f"<{n}I", ticks_blob[: 4 * n])
        zpos = struct.unpack(f"<{n}i", datas_blob[: 4 * n])
        return [{"tick": t, "step": z} for t, z in zip(ticks, zpos)]
